import fs from 'node:fs';
import {createHash} from 'node:crypto';
import {preflightDiagnosticReads} from '../runner/diagnostic-sql-preflight.mjs';
const SQL={scan:'SELECT ts_bucket,ts,universe_total,scanned,missing,errors,stale,stage0_coverage_pct,payload_json FROM scan_runs WHERE ts_bucket=?1 AND ts=?2 LIMIT 1',feature:'SELECT * FROM v3_early_feature_snapshot WHERE contract_code=?1 AND ts_bucket=?2 AND observed_ts=?3 LIMIT 1',queue:'SELECT state_key,status,updated_ts FROM tz101_entry_area_calibration_state WHERE state_key=?1 LIMIT 1',outcome:'SELECT outcome_id,outcome_status,computed_ts,raw_return_pct,mfe_pct,mae_pct FROM v3_early_outcome_journal WHERE outcome_id=?1 LIMIT 1'};
const readPreflight=preflightDiagnosticReads({schema:JSON.parse(fs.readFileSync(new URL('../current-generation/tests/fixtures/retained-native-diagnostic-columns-20261009.json',import.meta.url))),statements:Object.values(SQL)});
import {RemoteD1Database} from '../runner/report2-d1-adapter.mjs';
import {loadDailyUsageAggregate,evaluateDailyReservationBudget,reserveRunBudget,finalizeRunUsage} from '../runner/d1-preaction-budget-guard.mjs';
const db=new RemoteD1Database(process.env.REPORT2_D1_BRIDGE_URL,process.env.REPORT2_D1_BRIDGE_TOKEN),now=Date.now(),ts=1791552612763,bucket=Math.floor(ts/300000)*300000,reservation={rows_read:1000,rows_written:16},id='ORIGINAL_DIRECTION_INPUTS:'+process.env.GITHUB_RUN_ID+':'+process.env.GITHUB_RUN_ATTEMPT;
const out={readPreflight,schema:'EXACT_ORIGINAL_DIRECTION_INPUTS_V1',head:process.env.GITHUB_SHA,cloud_run:Number(process.env.GITHUB_RUN_ID),read_ts:now,original_run:37937215275,original_run_id:'1791552597150-1791552612560',original_scan_ts:ts,sourceHTTP:0,MAIN:0,Telegram:0,task_writes:0,outcome_writes:0,source_clocks_refreshed:false,project_complete:false};
out.admission=evaluateDailyReservationBudget({daily:await loadDailyUsageAggregate(db,now),nextReservation:reservation,maxDailyReads:3500000,maxDailyWrites:70000});
if(out.admission.allowed){await reserveRunBudget(db,{reservationId:id,now,reservation});try{
 out.original_scan=await db.prepare(SQL.scan).bind(bucket,ts).first();
 out.features=[];for(const contract of ['BR-USDT','BTR-USDT'])out.features.push({contract,feature:await db.prepare(SQL.feature).bind(contract,bucket,ts).first()});
 out.queue_states=[];for(const key of ['R8_20_OUTCOME_QUEUE_TURN_V1','R8_20_EARLY_OUTCOME_CURSOR_V1'])out.queue_states.push(await db.prepare(SQL.queue).bind(key).first());
 out.original_BR_h1=await db.prepare(SQL.outcome).bind('EDW:BR-USDT:1791545058092:G10:H1').first();
 out.producer_code=[];for(const name of fs.readdirSync('runtime/src').filter(x=>/^v3-early.*\.mjs$/.test(x))){const s=fs.readFileSync('runtime/src/'+name,'utf8'),lines=s.split('\n');out.producer_code.push({path:'runtime/src/'+name,sha256:createHash('sha256').update(s).digest('hex'),directional_formula_lines:lines.flatMap((line,i)=>/direction_state|DIRECTION_NOT_CLOSED|LONG_WATCH|SHORT_WATCH|long_evidence_domain_count|short_evidence_domain_count/.test(line)?[{line:i+1,text:line.slice(0,400)}]:[]).slice(0,60)});}
 const u=db.usageSnapshot();if(u.unknown_ops||u.rows_read>900||u.rows_written>14||u.requests>18)throw Error('READ_ENVELOPE_EXCEEDED');out.status='BOUNDED_ORIGINAL_DIRECTION_INPUTS_READ';out.original_scan_found=!!out.original_scan;out.original_features_found=out.features.filter(x=>x.feature).length;
 }catch(e){out.status='READ_NOT_CLOSED';out.error=String(e.message).slice(0,240);}finally{out.finalized_usage=await finalizeRunUsage(db,{reservationId:id,sourceRunId:process.env.GITHUB_RUN_ID,usage:db.usageSnapshot()});}}else out.status='D1_ADMISSION_BLOCKED';
out.D1=db.usageSnapshot();fs.mkdirSync('audit-output',{recursive:true});fs.writeFileSync('audit-output/original-direction-inputs.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify({status:out.status,original_scan_found:out.original_scan_found,original_features_found:out.original_features_found,D1:out.D1,error:out.error}));if(out.status!=='BOUNDED_ORIGINAL_DIRECTION_INPUTS_READ')process.exitCode=1;
